from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = [(r, c)]
            seen[r][c] = True
            comp = []
            for y, x in q:
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(comp) >= 4:
                comps.append((color, comp))

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                out[r][c] = bg

    for color, comp in comps:
        for r, c in comp:
            out[r][c] = color

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or out[r][c] != bg:
                continue
            neighbors = []
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                y, x = r + dr, c + dc
                if 0 <= y < h and 0 <= x < w and out[y][x] != bg:
                    neighbors.append(out[y][x])
            if len(neighbors) >= 2 and len(set(neighbors)) == 1:
                out[r][c] = neighbors[0]
    return out
